package api

import (
	"context"
	"encoding/base64"
	"errors"

	"github.com/google/uuid"
	"google.golang.org/grpc/codes"
	"google.golang.org/grpc/status"
	"google.golang.org/protobuf/types/known/timestamppb"

	agentv1 "github.com/zenithflowinc/omnicore-platform/platform/proto/gen/go/omnicore/agents/agent/v1"
	commonv1 "github.com/zenithflowinc/omnicore-platform/platform/proto/gen/go/omnicore/common/v1"
	"github.com/zenithflowinc/omnicore-platform/services/agents-svc/internal/registry"
	"github.com/zenithflowinc/omnicore-platform/services/agents-svc/internal/repo"
)

// defaultListAgentsPageSize / maxListAgentsPageSize bound ListAgents'
// page_size: zero (unset) falls back to the default, and any request
// asking for more than the max is clamped rather than rejected.
const (
	defaultListAgentsPageSize = int32(50)
	maxListAgentsPageSize     = int32(200)
)

// AgentHandler implements AgentDefinitionsServiceServer over
// repo.Repo — the Agent Builder save path (issue #1927): per-org agent
// instantiation from a template, validated against the tool/template
// registry.
type AgentHandler struct {
	agentv1.UnimplementedAgentDefinitionsServiceServer

	repo *repo.Repo
	reg  *registry.Registry
}

// NewAgentHandler constructs an AgentHandler backed by r and reg.
func NewAgentHandler(r *repo.Repo, reg *registry.Registry) *AgentHandler {
	return &AgentHandler{repo: r, reg: reg}
}

func (h *AgentHandler) CreateAgent(ctx context.Context, req *agentv1.CreateAgentRequest) (*agentv1.CreateAgentResponse, error) {
	a, err := h.repo.CreateAgent(ctx, h.reg, repo.CreateAgentInput{
		TemplateKey:             req.GetTemplateKey(),
		Name:                    req.GetName(),
		TokenBudget:             req.GetTokenBudget(),
		MaxIterations:           req.GetMaxIterations(),
		MaxWallClockSecs:        req.GetMaxWallClockSecs(),
		ConfirmationTimeoutSecs: req.GetConfirmationTimeoutSecs(),
		AutoWarmContext:         req.GetAutoWarmContext(),
		PreResearchMode:         req.GetPreResearchMode(),
		PlanFirstMode:           req.GetPlanFirstMode(),
	})
	if err != nil {
		return nil, toAgentGRPCStatus(err)
	}
	return &agentv1.CreateAgentResponse{Agent: agentToProto(a)}, nil
}

func (h *AgentHandler) UpdateAgent(ctx context.Context, req *agentv1.UpdateAgentRequest) (*agentv1.UpdateAgentResponse, error) {
	id, err := uuid.Parse(req.GetId())
	if err != nil {
		return nil, status.Error(codes.InvalidArgument, "invalid id")
	}

	a, err := h.repo.UpdateAgent(ctx, h.reg, repo.UpdateAgentInput{
		ID:                      id,
		Name:                    req.GetName(),
		TokenBudget:             req.GetTokenBudget(),
		MaxIterations:           req.GetMaxIterations(),
		MaxWallClockSecs:        req.GetMaxWallClockSecs(),
		ConfirmationTimeoutSecs: req.GetConfirmationTimeoutSecs(),
		AutoWarmContext:         req.GetAutoWarmContext(),
		PreResearchMode:         req.GetPreResearchMode(),
		PlanFirstMode:           req.GetPlanFirstMode(),
	})
	if err != nil {
		return nil, toAgentGRPCStatus(err)
	}
	if a.ID == uuid.Nil {
		return nil, status.Error(codes.NotFound, "agent not found")
	}
	return &agentv1.UpdateAgentResponse{Agent: agentToProto(a)}, nil
}

func (h *AgentHandler) GetAgent(ctx context.Context, req *agentv1.GetAgentRequest) (*agentv1.GetAgentResponse, error) {
	id, err := uuid.Parse(req.GetId())
	if err != nil {
		return nil, status.Error(codes.InvalidArgument, "invalid id")
	}

	a, err := h.repo.GetAgent(ctx, id)
	if err != nil {
		return nil, toAgentGRPCStatus(err)
	}
	if a.ID == uuid.Nil {
		return nil, status.Error(codes.NotFound, "agent not found")
	}
	return &agentv1.GetAgentResponse{Agent: agentToProto(a)}, nil
}

func (h *AgentHandler) ListAgents(ctx context.Context, req *agentv1.ListAgentsRequest) (*agentv1.ListAgentsResponse, error) {
	limit := req.GetPageSize()
	if limit <= 0 {
		limit = defaultListAgentsPageSize
	}
	if limit > maxListAgentsPageSize {
		limit = maxListAgentsPageSize
	}

	cursor, err := decodePageToken(req.GetPageToken())
	if err != nil {
		return nil, status.Error(codes.InvalidArgument, "invalid page_token")
	}

	// Fetch one extra row so we can tell whether another page exists
	// without a second round-trip.
	rows, err := h.repo.ListAgents(ctx, cursor, limit+1)
	if err != nil {
		return nil, toAgentGRPCStatus(err)
	}

	var nextPageToken string
	if int32(len(rows)) > limit {
		nextPageToken = encodePageToken(rows[limit-1].ID)
		rows = rows[:limit]
	}

	agents := make([]*agentv1.Agent, 0, len(rows))
	for _, a := range rows {
		agents = append(agents, agentToProto(a))
	}
	return &agentv1.ListAgentsResponse{Agents: agents, NextPageToken: nextPageToken}, nil
}

// decodePageToken decodes an opaque page token back into a keyset
// cursor. An empty token (the first page) decodes to uuid.Nil.
func decodePageToken(token string) (uuid.UUID, error) {
	if token == "" {
		return uuid.Nil, nil
	}
	raw, err := base64.RawURLEncoding.DecodeString(token)
	if err != nil {
		return uuid.Nil, err
	}
	return uuid.Parse(string(raw))
}

// encodePageToken opaquely encodes a keyset cursor as a page token.
func encodePageToken(id uuid.UUID) string {
	return base64.RawURLEncoding.EncodeToString([]byte(id.String()))
}

func agentToProto(a repo.AgentsAgent) *agentv1.Agent {
	out := &agentv1.Agent{
		Id:                      a.ID.String(),
		OrgId:                   &commonv1.OrgID{Value: a.OrgID.String()},
		TemplateKey:             a.TemplateKey,
		Name:                    a.Name,
		TokenBudget:             a.TokenBudget,
		MaxIterations:           a.MaxIterations,
		MaxWallClockSecs:        a.MaxWallClockSecs,
		ConfirmationTimeoutSecs: a.ConfirmationTimeoutSecs,
		AutoWarmContext:         a.AutoWarmContext,
		PreResearchMode:         a.PreResearchMode,
		PlanFirstMode:           a.PlanFirstMode,
	}
	if a.CreatedAt.Valid {
		out.CreatedAt = timestamppb.New(a.CreatedAt.Time)
	}
	return out
}

// toAgentGRPCStatus maps repo-layer errors to gRPC status codes.
// Distinct name from registry_handler.go's toGRPCStatus (same package,
// different error vocabulary) to avoid a symbol collision.
func toAgentGRPCStatus(err error) error {
	switch {
	case errors.Is(err, repo.ErrTemplateNotFound):
		return status.Error(codes.NotFound, err.Error())
	case errors.Is(err, repo.ErrTemplateToolKindViolation):
		return status.Error(codes.FailedPrecondition, err.Error())
	default:
		return status.Error(codes.Internal, err.Error())
	}
}


