package api

import (
	"context"
	"net/url"
	"path/filepath"
	"runtime"
	"testing"
	"time"

	"github.com/google/uuid"
	"github.com/jackc/pgx/v5"
	_ "github.com/jackc/pgx/v5/stdlib" // register "pgx" driver for goose
	"github.com/pressly/goose/v3"
	"github.com/stretchr/testify/require"
	"github.com/testcontainers/testcontainers-go"
	"github.com/testcontainers/testcontainers-go/modules/postgres"
	"github.com/testcontainers/testcontainers-go/wait"
	"google.golang.org/protobuf/proto"

	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/audit"
	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/auth"
	platformdb "github.com/zenithflowinc/omnicore-platform/platform/libs/go/db"
	agentv1 "github.com/zenithflowinc/omnicore-platform/platform/proto/gen/go/omnicore/agents/agent/v1"
	"github.com/zenithflowinc/omnicore-platform/services/agents-svc/internal/registry"
	"github.com/zenithflowinc/omnicore-platform/services/agents-svc/internal/repo"
)

// noopOutbox discards audit twins — these DB-backed API tests exercise the
// handler/repo write paths and don't need to assert on the outbox
// contents (see tests/integration/agent_definitions_handler_test.go for
// the audit-chain assertions).
type noopOutbox struct{}

func (noopOutbox) AddEvent(ctx context.Context, tx pgx.Tx, subject, msgID string, msg proto.Message) error {
	body, err := proto.Marshal(msg)
	if err != nil {
		return err
	}
	_, err = tx.Exec(ctx,
		`INSERT INTO agents.event_outbox (subject, msg_id, payload) VALUES ($1, $2, $3) ON CONFLICT (msg_id) DO NOTHING`,
		subject, msgID, body,
	)
	return err
}

func dsnAsAppUser(orig string) string {
	u, _ := url.Parse(orig)
	u.User = url.UserPassword("agents_app", "test_app")
	return u.String()
}

// startPostgresForAPITest boots a postgres testcontainer, applies the
// agents-svc migrations as the superuser, and returns a pool connected as
// the agents_app role (NOBYPASSRLS) so RLS is enforced — same shape as
// tests/integration/helpers_test.go's StartPostgres, self-contained here
// so internal/api's own unit-test run (no `integration` build tag)
// exercises AgentHandler's DB-backed RPCs directly, which is what drives
// this package's coverage floor.
func startPostgresForAPITest(t *testing.T) *platformdb.Pool {
	t.Helper()
	// Guarded in the helper, not per test: every caller needs the container,
	// and per-test guards drift — this package grew tests without one, which
	// is what `go test -short` on the daemon-less mac fleet caught. A guard
	// here cannot be forgotten by the next test added.
	if testing.Short() {
		t.Skip("requires testcontainers")
	}
	ctx := context.Background()
	pgC, err := postgres.Run(ctx,
		"postgres:16.4-alpine",
		postgres.WithDatabase("agents_api_test"),
		postgres.WithUsername("postgres"),
		postgres.WithPassword("test"),
		testcontainers.WithWaitStrategy(
			wait.ForLog("database system is ready to accept connections").
				WithOccurrence(2).
				WithStartupTimeout(60*time.Second),
		),
	)
	require.NoError(t, err)
	t.Cleanup(func() { _ = pgC.Terminate(ctx) })

	dsn, err := pgC.ConnectionString(ctx, "sslmode=disable")
	require.NoError(t, err)

	_, file, _, _ := runtime.Caller(0)
	migrationsDir := filepath.Join(filepath.Dir(file), "..", "..", "migrations")

	gooseDB, err := goose.OpenDBWithDriver("pgx", dsn)
	require.NoError(t, err)
	require.NoError(t, goose.SetDialect("postgres"))
	goose.SetTableName("goose_db_version_agents")
	require.NoError(t, goose.Up(gooseDB, migrationsDir))

	_, err = gooseDB.Exec(`ALTER ROLE agents_app WITH LOGIN PASSWORD 'test_app'`)
	require.NoError(t, err)
	require.NoError(t, gooseDB.Close())

	pool, err := platformdb.NewPool(ctx, dsnAsAppUser(dsn))
	require.NoError(t, err)
	t.Cleanup(pool.Close)
	return pool
}

func seedAgentTemplateForAPITest(t *testing.T, pool *platformdb.Pool, key, namespace, kind string, allowedTools []string) {
	t.Helper()
	ctx := context.Background()
	err := pool.WithTxNoTenant(ctx, func(tx pgx.Tx) error {
		_, err := tx.Exec(ctx,
			`INSERT INTO agents.agent_templates
			   (key, namespace, display_name, description, system_prompt, allowed_tools, kind)
			 VALUES ($1, $2, $3, $4, $5, $6, $7)
			 ON CONFLICT (key) DO NOTHING`,
			key, namespace, key+" display", key+" description", key+" system prompt", allowedTools, kind,
		)
		return err
	})
	require.NoError(t, err)
}

func tenantContextForAPITest(orgID, userID string) context.Context {
	return auth.HeadersIntoContext(context.Background(), auth.Headers{TenantID: orgID, UserID: userID})
}

func testKeyProviderForAPITest(t *testing.T) audit.KeyProvider {
	t.Helper()
	p, err := audit.NewEnvKeyProvider("test-v1:dGVzdC1hZ2VudHMtYXVkaXQtaG1hYy1rZXktMzItYiEh", "test-v1")
	require.NoError(t, err)
	return p
}

func TestAgentHandler_CreateGetUpdateList_HappyPath(t *testing.T) {
	pool := startPostgresForAPITest(t)
	seedAgentTemplateForAPITest(t, pool, "tmpl-api-happy", "clio", "specialist", []string{"search_documents"})

	r := repo.NewRepo(pool, &noopOutbox{}, testKeyProviderForAPITest(t))
	reg := registry.New(registry.Config{})
	h := NewAgentHandler(r, reg)

	orgID := uuid.New().String()
	ctx := tenantContextForAPITest(orgID, uuid.New().String())

	created, err := h.CreateAgent(ctx, &agentv1.CreateAgentRequest{
		TemplateKey: "tmpl-api-happy",
		Name:        "Happy Agent",
	})
	require.NoError(t, err)
	require.Equal(t, int32(100000), created.GetAgent().GetTokenBudget())

	got, err := h.GetAgent(ctx, &agentv1.GetAgentRequest{Id: created.GetAgent().GetId()})
	require.NoError(t, err)
	require.Equal(t, "Happy Agent", got.GetAgent().GetName())

	updated, err := h.UpdateAgent(ctx, &agentv1.UpdateAgentRequest{
		Id:   created.GetAgent().GetId(),
		Name: "Renamed",
	})
	require.NoError(t, err)
	require.Equal(t, "Renamed", updated.GetAgent().GetName())

	list, err := h.ListAgents(ctx, &agentv1.ListAgentsRequest{})
	require.NoError(t, err)
	require.Len(t, list.GetAgents(), 1)
}

func TestAgentHandler_GetAgent_InvalidID(t *testing.T) {
	pool := startPostgresForAPITest(t)
	r := repo.NewRepo(pool, &noopOutbox{}, testKeyProviderForAPITest(t))
	h := NewAgentHandler(r, registry.New(registry.Config{}))

	ctx := tenantContextForAPITest(uuid.New().String(), uuid.New().String())
	_, err := h.GetAgent(ctx, &agentv1.GetAgentRequest{Id: "not-a-uuid"})
	require.Error(t, err)
}

func TestAgentHandler_UpdateAgent_InvalidID(t *testing.T) {
	pool := startPostgresForAPITest(t)
	r := repo.NewRepo(pool, &noopOutbox{}, testKeyProviderForAPITest(t))
	h := NewAgentHandler(r, registry.New(registry.Config{}))

	ctx := tenantContextForAPITest(uuid.New().String(), uuid.New().String())
	_, err := h.UpdateAgent(ctx, &agentv1.UpdateAgentRequest{Id: "not-a-uuid"})
