}

func TestAgentHandler_GetAgent_NotFound(t *testing.T) {
	pool := startPostgresForAPITest(t)
	r := repo.NewRepo(pool, &noopOutbox{}, testKeyProviderForAPITest(t))
	h := NewAgentHandler(r, registry.New(registry.Config{}))

	ctx := tenantContextForAPITest(uuid.New().String(), uuid.New().String())
	_, err := h.GetAgent(ctx, &agentv1.GetAgentRequest{Id: uuid.New().String()})
	require.Error(t, err)
}

func TestAgentHandler_ListAgents_PaginatesWithNextPageToken(t *testing.T) {
	pool := startPostgresForAPITest(t)
	seedAgentTemplateForAPITest(t, pool, "tmpl-api-page", "clio", "specialist", []string{"search_documents"})

	r := repo.NewRepo(pool, &noopOutbox{}, testKeyProviderForAPITest(t))
	h := NewAgentHandler(r, registry.New(registry.Config{}))

	orgID := uuid.New().String()
	ctx := tenantContextForAPITest(orgID, uuid.New().String())

	for i := 0; i < 3; i++ {
		_, err := h.CreateAgent(ctx, &agentv1.CreateAgentRequest{TemplateKey: "tmpl-api-page", Name: "Agent"})
		require.NoError(t, err)
		time.Sleep(time.Millisecond)
	}

	page1, err := h.ListAgents(ctx, &agentv1.ListAgentsRequest{PageSize: 2})
	require.NoError(t, err)
	require.Len(t, page1.GetAgents(), 2)
	require.NotEmpty(t, page1.GetNextPageToken())

	page2, err := h.ListAgents(ctx, &agentv1.ListAgentsRequest{PageSize: 2, PageToken: page1.GetNextPageToken()})
	require.NoError(t, err)
	require.Len(t, page2.GetAgents(), 1)
	require.Empty(t, page2.GetNextPageToken())
}

func TestAgentHandler_ListAgents_InvalidPageToken(t *testing.T) {
	pool := startPostgresForAPITest(t)
	r := repo.NewRepo(pool, &noopOutbox{}, testKeyProviderForAPITest(t))
	h := NewAgentHandler(r, registry.New(registry.Config{}))

	ctx := tenantContextForAPITest(uuid.New().String(), uuid.New().String())
	_, err := h.ListAgents(ctx, &agentv1.ListAgentsRequest{PageToken: "not-valid-base64!!!"})
	require.Error(t, err)
}

