package api

import (
	"errors"
	"testing"

	"github.com/google/uuid"
	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
	"google.golang.org/grpc/codes"
	"google.golang.org/grpc/status"

	commonv1 "github.com/zenithflowinc/omnicore-platform/platform/proto/gen/go/omnicore/common/v1"
	"github.com/zenithflowinc/omnicore-platform/services/agents-svc/internal/repo"
)

func TestToAgentGRPCStatus_MapsKnownRepoErrors(t *testing.T) {
	tests := []struct {
		name string
		err  error
		want codes.Code
	}{
		{"template not found -> NotFound", repo.ErrTemplateNotFound, codes.NotFound},
		{"tool-kind violation -> FailedPrecondition", repo.ErrTemplateToolKindViolation, codes.FailedPrecondition},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			err := toAgentGRPCStatus(tt.err)
			st, ok := status.FromError(err)
			require.True(t, ok)
			assert.Equal(t, tt.want, st.Code())
		})
	}
}

func TestToAgentGRPCStatus_DefaultsToInternal(t *testing.T) {
	err := toAgentGRPCStatus(errors.New("boom"))
	st, ok := status.FromError(err)
	require.True(t, ok)
	assert.Equal(t, codes.Internal, st.Code())
}

func TestDecodeEncodePageToken_RoundTrips(t *testing.T) {
	id := uuid.New()

	token := encodePageToken(id)
	assert.NotEmpty(t, token)

	got, err := decodePageToken(token)
	require.NoError(t, err)
	assert.Equal(t, id, got)
}

func TestDecodePageToken_EmptyIsNilCursor(t *testing.T) {
	got, err := decodePageToken("")
	require.NoError(t, err)
	assert.Equal(t, uuid.Nil, got)
}

func TestDecodePageToken_InvalidToken_Errors(t *testing.T) {
	_, err := decodePageToken("not-valid-base64!!!")
	assert.Error(t, err)
}

func TestAgentToProto_MapsAllFields(t *testing.T) {
	id := uuid.New()
	orgID := uuid.New()

	a := repo.AgentsAgent{
		ID:                      id,
		OrgID:                   orgID,
		TemplateKey:             "tmpl-x",
		Name:                    "My Agent",
		TokenBudget:             1000,
		MaxIterations:           5,
		MaxWallClockSecs:        60,
		ConfirmationTimeoutSecs: 120,
		AutoWarmContext:         true,
		PreResearchMode:         true,
		PlanFirstMode:           false,
	}

	out := agentToProto(a)

	assert.Equal(t, id.String(), out.GetId())
	assert.Equal(t, &commonv1.OrgID{Value: orgID.String()}, out.GetOrgId())
	assert.Equal(t, "tmpl-x", out.GetTemplateKey())
	assert.Equal(t, "My Agent", out.GetName())
	assert.Equal(t, int32(1000), out.GetTokenBudget())
	assert.Equal(t, int32(5), out.GetMaxIterations())
	assert.Equal(t, int32(60), out.GetMaxWallClockSecs())
	assert.Equal(t, int32(120), out.GetConfirmationTimeoutSecs())
	assert.True(t, out.GetAutoWarmContext())
	assert.True(t, out.GetPreResearchMode())
	assert.False(t, out.GetPlanFirstMode())
	assert.Nil(t, out.GetCreatedAt(), "zero-value pgtype.Timestamptz must not populate created_at")
}

func TestNewAgentHandler_ConstructsWithoutPanicking(t *testing.T) {
	h := NewAgentHandler(nil, nil)
	assert.NotNil(t, h)
}


