package api

import (
	"context"
	"errors"

	"google.golang.org/grpc/codes"
	"google.golang.org/grpc/status"

	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/auth"
	registryv1 "github.com/zenithflowinc/omnicore-platform/platform/proto/gen/go/omnicore/agents/registry/v1"
	"github.com/zenithflowinc/omnicore-platform/services/agents-svc/internal/registry"
)

// registerAllowedAZP maps a registrable namespace to the single azp
// permitted to call RegisterToolset/RegisterTemplates/FreezeRegistry for
// it — these are service-to-service RPCs (proto doc: "vertical service's
// RegisterToolset call (e.g. namespace 'clio')"), not caller-supplied
// data to trust at face value. A namespace absent from this table
// (including "", already rejected by registry.ErrReservedNamespace) is
// never permitted, regardless of azp.
var registerAllowedAZP = map[string]string{
	"clio": "clio-svc",
}

// authorizedForNamespace enforces registerAllowedAZP: the caller's azp
// claim must be the single service that owns namespace.
func authorizedForNamespace(ctx context.Context, namespace string) error {
	claims, ok := auth.ClaimsFromContext(ctx)
	if !ok {
		return status.Error(codes.PermissionDenied, "requires authenticated claims")
	}
	allowedAZP, known := registerAllowedAZP[namespace]
	if !known || claims.AZP != allowedAZP {
		return status.Errorf(codes.PermissionDenied, "namespace %q is not registrable by this caller", namespace)
	}
	return nil
}

// RegistryHandler implements AgentRegistryServiceServer over an in-memory
// registry.Registry.
type RegistryHandler struct {
	registryv1.UnimplementedAgentRegistryServiceServer

	reg *registry.Registry
}

// NewRegistryHandler constructs a RegistryHandler backed by reg.
func NewRegistryHandler(reg *registry.Registry) *RegistryHandler {
	return &RegistryHandler{reg: reg}
}

func (h *RegistryHandler) RegisterToolset(ctx context.Context, req *registryv1.RegisterToolsetRequest) (*registryv1.RegisterToolsetResponse, error) {
	if err := authorizedForNamespace(ctx, req.GetNamespace()); err != nil {
		return nil, err
	}

	tools := make([]registry.Tool, 0, len(req.GetTools()))
	for _, t := range req.GetTools() {
		tools = append(tools, registry.Tool{
			Namespace:            req.GetNamespace(),
			Name:                 t.GetName(),
			Description:          t.GetDescription(),
			JSONSchema:           t.GetJsonSchema(),
			OrchestratorOnly:     t.GetOrchestratorOnly(),
			RequiresConfirmation: t.GetRequiresConfirmation(),
		})
	}

	n, err := h.reg.RegisterToolset(req.GetNamespace(), tools)
	if err != nil {
		return nil, toGRPCStatus(err)
	}
	return &registryv1.RegisterToolsetResponse{RegisteredCount: int32(n)}, nil
}

func (h *RegistryHandler) RegisterTemplates(ctx context.Context, req *registryv1.RegisterTemplatesRequest) (*registryv1.RegisterTemplatesResponse, error) {
	if err := authorizedForNamespace(ctx, req.GetNamespace()); err != nil {
		return nil, err
	}

	templates := make([]registry.Template, 0, len(req.GetTemplates()))
	for _, t := range req.GetTemplates() {
		templates = append(templates, registry.Template{
			Key:          t.GetKey(),
			Namespace:    req.GetNamespace(),
			DisplayName:  t.GetDisplayName(),
			Description:  t.GetDescription(),
			SystemPrompt: t.GetSystemPrompt(),
			AllowedTools: t.GetAllowedTools(),
			Temperature:  t.GetTemperature(),
			Kind:         t.GetKind(),
			Visibility:   t.GetVisibility(),
		})
	}

	n, err := h.reg.RegisterTemplates(req.GetNamespace(), templates)
	if err != nil {
		return nil, toGRPCStatus(err)
	}
	return &registryv1.RegisterTemplatesResponse{RegisteredCount: int32(n)}, nil
}

func (h *RegistryHandler) FreezeRegistry(ctx context.Context, req *registryv1.FreezeRegistryRequest) (*registryv1.FreezeRegistryResponse, error) {
	if err := authorizedForNamespace(ctx, req.GetNamespace()); err != nil {
		return nil, err
	}

	frozen, count := h.reg.Freeze(req.GetNamespace())
	return &registryv1.FreezeRegistryResponse{Frozen: frozen, ToolCount: int32(count)}, nil
}

func (h *RegistryHandler) ListTools(_ context.Context, req *registryv1.ListToolsRequest) (*registryv1.ListToolsResponse, error) {
	tools := h.reg.ListTools(req.GetKind())
	out := make([]*registryv1.ToolSpec, 0, len(tools))
	for _, t := range tools {
		out = append(out, &registryv1.ToolSpec{
			Namespace:            t.Namespace,
			Name:                 t.Name,
			Description:          t.Description,
			JsonSchema:           t.JSONSchema,
			OrchestratorOnly:     t.OrchestratorOnly,
			RequiresConfirmation: t.RequiresConfirmation,
		})
	}
	return &registryv1.ListToolsResponse{Tools: out}, nil
}

func toGRPCStatus(err error) error {
	switch {
	case errors.Is(err, registry.ErrRegistryFrozen):
		return status.Error(codes.FailedPrecondition, err.Error())
	case errors.Is(err, registry.ErrReservedNamespace):
		return status.Error(codes.InvalidArgument, err.Error())
	default:
		return status.Error(codes.Internal, err.Error())
	}
}


