package api

import (
	"context"
	"encoding/json"
	"errors"
	"time"

	"github.com/google/uuid"
	"google.golang.org/grpc/codes"
	"google.golang.org/grpc/status"
	"google.golang.org/protobuf/types/known/timestamppb"

	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/auth"
	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/observability"
	runv1 "github.com/zenithflowinc/omnicore-platform/platform/proto/gen/go/omnicore/agents/run/v1"
	commonv1 "github.com/zenithflowinc/omnicore-platform/platform/proto/gen/go/omnicore/common/v1"
	"github.com/zenithflowinc/omnicore-platform/services/agents-svc/internal/execution"
	"github.com/zenithflowinc/omnicore-platform/services/agents-svc/internal/repo"
)

// streamRunEventsPollInterval bounds how often StreamRunEvents re-queries
// for events past the client's last-seen seq while a run is still live
// (issue #1930). The executor's think→act→observe loop runs synchronously
// within CreateRun/ConfirmPendingCall (no fan-out/pubsub hook exists yet),
// so "live" here means poll-until-terminal rather than a pushed
// notification — by the time a client can call StreamRunEvents a run is
// very often already terminal, but the poll loop also serves a
// still-open (awaiting_confirmation) run and a genuine reconnect.
var streamRunEventsPollInterval = 50 * time.Millisecond

// runModeFromProto/runModeToProto translate between the proto RunMode
// enum and the "interactive"|"autonomous" string stored in the run_mode
// column (CHECK-constrained to those two values).
var runModeFromProtoMap = map[runv1.RunMode]string{
	runv1.RunMode_RUN_MODE_INTERACTIVE: "interactive",
	runv1.RunMode_RUN_MODE_AUTONOMOUS:  "autonomous",
}

var runModeToProtoMap = map[string]runv1.RunMode{
	"interactive": runv1.RunMode_RUN_MODE_INTERACTIVE,
	"autonomous":  runv1.RunMode_RUN_MODE_AUTONOMOUS,
}

var runStatusToProtoMap = map[string]runv1.RunStatus{
	"running":               runv1.RunStatus_RUN_STATUS_RUNNING,
	"awaiting_confirmation": runv1.RunStatus_RUN_STATUS_AWAITING_CONFIRMATION,
	"completed":             runv1.RunStatus_RUN_STATUS_COMPLETED,
	"canceled":              runv1.RunStatus_RUN_STATUS_CANCELED,
	"error":                 runv1.RunStatus_RUN_STATUS_ERROR,
}

// RunHandler implements AgentRunsServiceServer. CreateRun (issue #1928)
// and CancelRun/ConfirmPendingCall (issue #1929) are real, delegating to
// the executor's think→act→observe loop; GetRun/ListRuns/StreamRunEvents
// stay UNIMPLEMENTED (#1930's scope).
type RunHandler struct {
	runv1.UnimplementedAgentRunsServiceServer

	ex *execution.Executor
}

// NewRunHandler constructs a RunHandler backed by ex. ex may be nil for
// tests exercising only the still-Unimplemented methods, which never
// touch it.
func NewRunHandler(ex *execution.Executor) *RunHandler {
	return &RunHandler{ex: ex}
}

// CreateRun translates the request into execution.CreateRunInput, drives
// the executor's think→act→observe loop synchronously, and returns the
// run's final, terminal post-image. An unpermitted/unknown tool call
// terminates the run with terminated_reason="error" rather than failing
// the RPC — only infra-level failures (cross-tenant agent id, DB errors)
// surface as a gRPC error.
func (h *RunHandler) CreateRun(ctx context.Context, req *runv1.CreateRunRequest) (*runv1.CreateRunResponse, error) {
	agentID, err := uuid.Parse(req.GetAgentId())
	if err != nil {
		return nil, status.Error(codes.InvalidArgument, "invalid agent_id")
	}

	var chatID uuid.UUID
	if req.GetChatId() != "" {
		chatID, err = uuid.Parse(req.GetChatId())
		if err != nil {
			return nil, status.Error(codes.InvalidArgument, "invalid chat_id")
		}
	}

	runMode, ok := runModeFromProtoMap[req.GetRunMode()]
	if !ok {
		return nil, status.Error(codes.InvalidArgument, "invalid run_mode")
	}

	h2 := auth.HeadersFromContext(ctx)
	userID, err := uuid.Parse(h2.UserID)
	if err != nil {
		return nil, status.Error(codes.Unauthenticated, "missing or invalid user id")
	}

	inputPayload := []byte(req.GetInputPayloadJson())
	if len(inputPayload) == 0 {
		inputPayload = []byte("{}")
	}

	run, err := h.ex.CreateRun(ctx, execution.CreateRunInput{
		AgentID:      agentID,
		UserID:       userID,
		ChatID:       chatID,
		RunMode:      runMode,
		InputPayload: inputPayload,
	})
	if err != nil {
		return nil, toRunGRPCStatus(err)
	}

	return &runv1.CreateRunResponse{Run: runToProto(run)}, nil
}

// ConfirmPendingCall resumes a run paused for confirmation (issue #1929).
func (h *RunHandler) ConfirmPendingCall(ctx context.Context, req *runv1.ConfirmPendingCallRequest) (*runv1.ConfirmPendingCallResponse, error) {
	runID, err := uuid.Parse(req.GetRunId())
	if err != nil {
		return nil, status.Error(codes.InvalidArgument, "invalid run_id")
	}

	run, err := h.ex.ConfirmPendingCall(ctx, runID, req.GetApprove())
	if err != nil {
		return nil, toRunGRPCStatus(err)
	}
	return &runv1.ConfirmPendingCallResponse{Run: runToProto(run)}, nil
}

// CancelRun requests cancellation of a run (issue #1929).
func (h *RunHandler) CancelRun(ctx context.Context, req *runv1.CancelRunRequest) (*runv1.CancelRunResponse, error) {
	runID, err := uuid.Parse(req.GetRunId())
	if err != nil {
		return nil, status.Error(codes.InvalidArgument, "invalid run_id")
	}

	run, err := h.ex.CancelRun(ctx, runID)
	if err != nil {
		return nil, toRunGRPCStatus(err)
	}
	return &runv1.CancelRunResponse{Run: runToProto(run)}, nil
}

// terminalRunStatuses are the run_mode-independent statuses at which a
// run will never produce another run_event — StreamRunEvents stops
// polling and closes the stream once it observes one of these.
var terminalRunStatuses = map[string]bool{
	"completed": true,
	"canceled":  true,
	"error":     true,
}

// finalEventPayload is the JSON body of the synthetic "final" event
// StreamRunEvents appends once a run reaches a terminal status. It is
// never persisted as a run_events row — it is derived from the run's own
// terminal columns at stream time, so replaying the same run twice
// produces the same gap-free sequence plus the same final marker.
type finalEventPayload struct {
	Status           string `json:"status"`
	TerminatedReason string `json:"terminated_reason,omitempty"`
}

// StreamRunEvents replays a run's persisted run_events in seq order, then
// polls for further events until the run reaches a terminal status
// (issue #1930), at which point it appends one synthetic "final" event
// and closes the stream. A run_id belonging to another tenant surfaces as
// NotFound (RLS makes it indistinguishable from a missing run — see
// repo.GetRun), matching every other RunHandler method's cross-tenant
// behavior. Replaying the same run_id again (a reconnect) yields the same
// gap-free sequence, since nothing here depends on prior stream state.
func (h *RunHandler) StreamRunEvents(req *runv1.StreamRunEventsRequest, stream runv1.AgentRunsService_StreamRunEventsServer) error {
	runID, err := uuid.Parse(req.GetRunId())
	if err != nil {
		return status.Error(codes.InvalidArgument, "invalid run_id")
	}

	ctx := stream.Context()
	repository := h.ex.Repo()

	var lastSeq int64
	ticker := time.NewTicker(streamRunEventsPollInterval)
	defer ticker.Stop()

	for {
		run, err := repository.GetRun(ctx, runID)
		if err != nil {
			return toRunGRPCStatus(err)
		}

		events, err := repository.ListRunEventsAfterSeq(ctx, runID, lastSeq)
		if err != nil {
			return status.Error(codes.Internal, err.Error())
		}
		for _, ev := range events {
			if err := stream.Send(&runv1.StreamRunEventsResponse{Event: runEventToProto(ev)}); err != nil {
				return err
			}
			lastSeq = ev.Seq
		}

		if terminalRunStatuses[run.Status] {
			terminatedReason := ""
			if run.TerminatedReason != nil {
				terminatedReason = *run.TerminatedReason
			}
			payload, err := json.Marshal(finalEventPayload{Status: run.Status, TerminatedReason: terminatedReason})
			if err != nil {
				return status.Error(codes.Internal, err.Error())
			}
			return stream.Send(&runv1.StreamRunEventsResponse{Event: &runv1.RunEvent{
				RunId:       runID.String(),
				Seq:         lastSeq + 1,
				EventType:   "final",
				PayloadJson: string(payload),
				CreatedAt:   timestamppb.Now(),
			}})
		}

		select {
		case <-ctx.Done():
			return status.FromContextError(ctx.Err()).Err()
		case <-ticker.C:
		}
	}
}

func runEventToProto(ev repo.AgentsRunEvent) *runv1.RunEvent {
	out := &runv1.RunEvent{
		RunId:       ev.RunID.String(),
		Seq:         ev.Seq,
		EventType:   ev.EventType,
		PayloadJson: string(ev.Payload),
	}
	if ev.CreatedAt.Valid {
		out.CreatedAt = timestamppb.New(ev.CreatedAt.Time)
	}
	return out
}

func runToProto(r repo.AgentsAgentRun) *runv1.Run {
	out := &runv1.Run{
		Id:                   r.ID.String(),
		AgentId:              r.AgentID.String(),
		RunMode:              runModeToProtoMap[r.RunMode],
		Status:               runStatusToProtoMap[r.Status],
		TokensUsed:           r.TokensUsed,
		IterationsUsed:       r.IterationsUsed,
		ElapsedSeconds:       r.ElapsedSeconds,
		AwaitingConfirmation: r.AwaitingConfirmation,
	}
	if r.OrgID != uuid.Nil {
		out.OrgId = &commonv1.OrgID{Value: r.OrgID.String()}
	}
	if r.UserID != uuid.Nil {
		out.UserId = &commonv1.UserID{Value: r.UserID.String()}
	}
	if r.ChatID != nil {
		out.ChatId = r.ChatID.String()
	}
	if r.ParentRunID != nil {
		out.ParentRunId = r.ParentRunID.String()
	}
	if r.TerminatedReason != nil {
		out.TerminatedReason = *r.TerminatedReason
	}
	if r.CreatedAt.Valid {
		out.CreatedAt = timestamppb.New(r.CreatedAt.Time)
	}
	if r.UpdatedAt.Valid {
		out.UpdatedAt = timestamppb.New(r.UpdatedAt.Time)
	}
	return out
}

// toRunGRPCStatus maps execution/repo-layer errors to gRPC status codes.
func toRunGRPCStatus(err error) error {
	var obsErr *observability.Error
	if errors.As(err, &obsErr) {
		switch obsErr.Code {
		case observability.CodeNotFound:
			return status.Error(codes.NotFound, obsErr.Error())
		case observability.CodeForbidden:
			return status.Error(codes.PermissionDenied, obsErr.Error())
		}
	}
	if errors.Is(err, execution.ErrAgentNotFound) {
		return status.Error(codes.NotFound, err.Error())
	}
	return status.Error(codes.Internal, err.Error())
}


