// scriptedToolExecutorForAPITest is a minimal fake execution.ToolExecutor
// for StreamRunEvents tests that need at least one persisted tool_call
// event replayed (runEventToProto's non-final path).
type scriptedToolExecutorForAPITest struct {
	mu    sync.Mutex
	steps []struct {
		call   execution.ToolCall
		result execution.ExecuteToolResult
	}
	next int
}

func (f *scriptedToolExecutorForAPITest) NextCall(_ context.Context, _ repo.AgentsAgentRun, _ int) (execution.ToolCall, error) {
	f.mu.Lock()
	defer f.mu.Unlock()
	return f.steps[f.next].call, nil
}

func (f *scriptedToolExecutorForAPITest) ExecuteTool(_ context.Context, _ string, _ map[string]any) (execution.ExecuteToolResult, error) {
	f.mu.Lock()
	defer f.mu.Unlock()
	result := f.steps[f.next].result
	f.next++
	return result, nil
}

