// Package api contains the gRPC server wiring and request handlers for
// agents-svc.
package api

import (
	"context"
	"strings"

	"google.golang.org/grpc"
	"google.golang.org/grpc/health"
	healthpb "google.golang.org/grpc/health/grpc_health_v1"

	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/auth"
	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/observability"
	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/validate"
	agentv1 "github.com/zenithflowinc/omnicore-platform/platform/proto/gen/go/omnicore/agents/agent/v1"
	registryv1 "github.com/zenithflowinc/omnicore-platform/platform/proto/gen/go/omnicore/agents/registry/v1"
	runv1 "github.com/zenithflowinc/omnicore-platform/platform/proto/gen/go/omnicore/agents/run/v1"
	"github.com/zenithflowinc/omnicore-platform/services/agents-svc/internal/execution"
	"github.com/zenithflowinc/omnicore-platform/services/agents-svc/internal/registry"
	"github.com/zenithflowinc/omnicore-platform/services/agents-svc/internal/repo"
)

// healthExemptInterceptor wraps the auth interceptor so that the gRPC health
// service (/grpc.health.v1.Health/*) bypasses JWT validation. All other
// methods remain under AuthRequired.
func healthExemptInterceptor(verifier *auth.JWTVerifier) grpc.UnaryServerInterceptor {
	authInterceptor := auth.UnaryServerInterceptor(verifier, auth.AuthRequired)
	return func(ctx context.Context, req any, info *grpc.UnaryServerInfo, handler grpc.UnaryHandler) (any, error) {
		if strings.HasPrefix(info.FullMethod, "/grpc.health.v1.Health/") {
			return handler(ctx, req)
		}
		return authInterceptor(ctx, req, info, handler)
	}
}

// NewGRPCServer creates a new grpc.Server with metrics + auth + health
// interceptors and registers AgentRegistryService, AgentRunsService, and
// AgentDefinitionsService.
//
// Interceptor order (outermost → innermost per mtls-jwt-auth skill):
//  1. UnaryServerMetricsInterceptor — times the full handler including auth.
//  2. healthExemptInterceptor — passes health check RPCs through without JWT;
//     all other RPCs go through auth.UnaryServerInterceptor.
//  3. validate.MustUnaryServerInterceptor — buf.validate rule enforcement,
//     placed after auth/health so CEL evaluation and validation-error
//     detail are never spent on / leaked to an unauthenticated caller.
//
// SetupMeter must be called before NewGRPCServer.
func NewGRPCServer(
	verifier *auth.JWTVerifier,
	reg *registry.Registry,
	agentRepo *repo.Repo,
	ex *execution.Executor,
	extraOpts ...grpc.ServerOption,
) *grpc.Server {
	opts := []grpc.ServerOption{
		grpc.ChainUnaryInterceptor(
			observability.UnaryServerMetricsInterceptor(),
			healthExemptInterceptor(verifier),
			validate.MustUnaryServerInterceptor(),
		),
	}
	opts = append(opts, observability.GRPCServerOptions())
	opts = append(opts, extraOpts...)

	s := grpc.NewServer(opts...)

	registryv1.RegisterAgentRegistryServiceServer(s, NewRegistryHandler(reg))
	runv1.RegisterAgentRunsServiceServer(s, NewRunHandler(ex))
	agentv1.RegisterAgentDefinitionsServiceServer(s, NewAgentHandler(agentRepo, reg))

	hs := health.NewServer()
	hs.SetServingStatus("", healthpb.HealthCheckResponse_SERVING)
	healthpb.RegisterHealthServer(s, hs)

	return s
}


