// handler/repo write paths and don't need to assert on the outbox
// contents (see tests/integration/agent_definitions_handler_test.go for
// the audit-chain assertions).
type noopOutbox struct{}

func (noopOutbox) AddEvent(ctx context.Context, tx pgx.Tx, subject, msgID string, msg proto.Message) error {
	body, err := proto.Marshal(msg)
	if err != nil {
		return err
	}
	_, err = tx.Exec(ctx,
		`INSERT INTO agents.event_outbox (subject, msg_id, payload) VALUES ($1, $2, $3) ON CONFLICT (msg_id) DO NOTHING`,
		subject, msgID, body,
	)
	return err
}

func dsnAsAppUser(orig string) string {
	u, _ := url.Parse(orig)
	u.User = url.UserPassword("agents_app", "test_app")
	return u.String()
}

// startPostgresForAPITest boots a postgres testcontainer, applies the
// agents-svc migrations as the superuser, and returns a pool connected as
// the agents_app role (NOBYPASSRLS) so RLS is enforced — same shape as
// tests/integration/helpers_test.go's StartPostgres, self-contained here
// so internal/api's own unit-test run (no `integration` build tag)
// exercises AgentHandler's DB-backed RPCs directly, which is what drives
// this package's coverage floor.
func startPostgresForAPITest(t *testing.T) *platformdb.Pool {
	t.Helper()
	// Guarded in the helper, not per test: every caller needs the container,
	// and per-test guards drift — this package grew tests without one, which
	// is what `go test -short` on the daemon-less mac fleet caught. A guard
	// here cannot be forgotten by the next test added.
	if testing.Short() {
		t.Skip("requires testcontainers")
	}
	ctx := context.Background()
	pgC, err := postgres.Run(ctx,
		"postgres:16.4-alpine",
		postgres.WithDatabase("agents_api_test"),
		postgres.WithUsername("postgres"),
		postgres.WithPassword("test"),
		testcontainers.WithWaitStrategy(
			wait.ForLog("database system is ready to accept connections").
				WithOccurrence(2).
				WithStartupTimeout(60*time.Second),
		),
	)
	require.NoError(t, err)
	t.Cleanup(func() { _ = pgC.Terminate(ctx) })

	dsn, err := pgC.ConnectionString(ctx, "sslmode=disable")
	require.NoError(t, err)

	_, file, _, _ := runtime.Caller(0)
	migrationsDir := filepath.Join(filepath.Dir(file), "..", "..", "migrations")

	gooseDB, err := goose.OpenDBWithDriver("pgx", dsn)
	require.NoError(t, err)
	require.NoError(t, goose.SetDialect("postgres"))
	goose.SetTableName("goose_db_version_agents")
	require.NoError(t, goose.Up(gooseDB, migrationsDir))

	_, err = gooseDB.Exec(`ALTER ROLE agents_app WITH LOGIN PASSWORD 'test_app'`)
	require.NoError(t, err)
	require.NoError(t, gooseDB.Close())

	pool, err := platformdb.NewPool(ctx, dsnAsAppUser(dsn))
	require.NoError(t, err)
	t.Cleanup(pool.Close)
	return pool
}

