// scriptedToolExecutorForAPITest is a minimal fake execution.ToolExecutor
// for StreamRunEvents tests that need at least one persisted tool_call
// event replayed (runEventToProto's non-final path).
type scriptedToolExecutorForAPITest struct {
	mu    sync.Mutex
	steps []struct {
		call   execution.ToolCall
		result execution.ExecuteToolResult
	}
	next int
}

func (f *scriptedToolExecutorForAPITest) NextCall(_ context.Context, _ repo.AgentsAgentRun, _ int) (execution.ToolCall, error) {
	f.mu.Lock()
	defer f.mu.Unlock()
	return f.steps[f.next].call, nil
}

func (f *scriptedToolExecutorForAPITest) ExecuteTool(_ context.Context, _ string, _ map[string]any) (execution.ExecuteToolResult, error) {
	f.mu.Lock()
	defer f.mu.Unlock()
	result := f.steps[f.next].result
	f.next++
	return result, nil
}

// TestRunHandler_StreamRunEvents_ReplaysPersistedToolCallEvents covers
// runEventToProto's non-final path: a persisted tool_call event replays
// with its own seq/event_type/payload ahead of the synthetic final event.
func TestRunHandler_StreamRunEvents_ReplaysPersistedToolCallEvents(t *testing.T) {
	pool := startPostgresForAPITest(t)
	seedAgentTemplateForAPITest(t, pool, "tmpl-run-api-stream-events", "clio", "specialist", []string{"search_documents"})

	r := repo.NewRepo(pool, &noopOutbox{}, testKeyProviderForAPITest(t))
	reg := registry.New(registry.Config{})
	agentHandler := NewAgentHandler(r, reg)

	ctx := tenantContextForAPITest(uuid.New().String(), uuid.New().String())
	createdAgent, err := agentHandler.CreateAgent(ctx, &agentv1.CreateAgentRequest{
		TemplateKey: "tmpl-run-api-stream-events",
		Name:        "Stream Events API Agent",
	})
	require.NoError(t, err)

	fake := &scriptedToolExecutorForAPITest{steps: []struct {
		call   execution.ToolCall
		result execution.ExecuteToolResult
	}{
		{call: execution.ToolCall{ToolName: "search_documents", Args: map[string]any{"q": "x"}, TokensUsed: 1}, result: execution.ExecuteToolResult{OK: true}},
		{call: execution.ToolCall{Done: true}},
	}}
	ex := execution.NewExecutor(r, reg, fake)
	h := NewRunHandler(ex)

	createResp, err := h.CreateRun(ctx, &runv1.CreateRunRequest{
		AgentId:          createdAgent.GetAgent().GetId(),
		RunMode:          runv1.RunMode_RUN_MODE_AUTONOMOUS,
		InputPayloadJson: `{}`,
	})
	require.NoError(t, err)
	require.Equal(t, "completed", createResp.GetRun().GetTerminatedReason())

	stream := &fakeStreamServer{ctx: ctx}
	err = h.StreamRunEvents(&runv1.StreamRunEventsRequest{RunId: createResp.GetRun().GetId()}, stream)
	require.NoError(t, err)

	got := stream.responses()
	require.Len(t, got, 2, "1 persisted tool_call + 1 synthetic final")
	require.Equal(t, int64(1), got[0].GetEvent().GetSeq())
	require.Equal(t, "tool_call", got[0].GetEvent().GetEventType())
	require.NotEmpty(t, got[0].GetEvent().GetRunId())
	require.NotNil(t, got[0].GetEvent().GetCreatedAt())
	require.Equal(t, "final", got[1].GetEvent().GetEventType())
}


