// TestHealthExemptInterceptor_BypassesAuthForHealthCheck exercises the
// health-check bypass branch of healthExemptInterceptor — the only branch
// safely reachable with a nil *auth.JWTVerifier, since the non-health
// branch dials into real JWT verification.
func TestHealthExemptInterceptor_BypassesAuthForHealthCheck(t *testing.T) {
	interceptor := healthExemptInterceptor(nil)

	called := false
	handler := func(ctx context.Context, req any) (any, error) {
		called = true
		return "ok", nil
	}

	resp, err := interceptor(context.Background(), nil, &grpc.UnaryServerInfo{
		FullMethod: "/grpc.health.v1.Health/Check",
	}, handler)
	require.NoError(t, err)
	assert.Equal(t, "ok", resp)
	assert.True(t, called, "health-check RPCs must bypass JWT validation")
}



